CREATE TABLE q(test,expr); INSERT INTO q VALUES('1','"M B"'),('2','"B D"'),('3','"M B D"'); CREATE TABLE result AS SELECT test,'ASC' AS direction,(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid ASC)) AS docs FROM q UNION ALL SELECT test,'DESC',(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid DESC)) FROM q;